/**
 * @method
 * @name ipt_totAsstAmt_onclick
 * @description ipt_totAsstAmt 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_totAsstAmt_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.select()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05023.ipt_totAsstAmt_onclick' }); }
};

/**
 * @method
 * @name ipt_totAsstAmt_onkeyup
 * @description ipt_totAsstAmt 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_totAsstAmt_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (selfVar.value = $c.num.formatNumber(selfVar.value));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05023.ipt_totAsstAmt_onkeyup' }); }
};

