/**
 * @method
 * @name onCloseCalendar
 * @description on Close Calendar 처리
 * @returns {void}
 * @hidden N
 */
scwin.onCloseCalendar = function () {
    if (scwin.openCalendarObj === scwin.form.basDd[0] || scwin.openCalendarObj === scwin.form.basDd[1]) {
        return;
    }
    scwin.openCalendarObj.value = scwin.openCalendarObj.value.substring(0, 6);
    scwin.paramCalendarObj.value = scwin.openCalendarObj.value;
};

/**
 * @method
 * @name vailidationLn
 * @description vailidation Ln 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.vailidationLn = async function () {
    for (i = 0; i < 3; i++) {
        const arrObj = $c.util.getComponent('slc_audtOpinTpCd');
        if (arrObj[i].value === '') {
            await $c.win.alert('해당사항을 선택하셔야 합니다.');
            $c.util.getComponent("slc_audtOpinTpCd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (!await scwin.isPossibleSave()) {
        return;
    }
    if (!await scwin.vailidationLn()) {
        return;
    }
    const CheckArrDateArrVar1 = ['acntclsYymm'];
    const CheckArrDateArrVar2 = ['basDd'];
    if (!fn_IsValidArrDate(scwin.form, CheckArrDateArrVar1, 6)) {  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_IsValidArrDate — 폼·DOM 의존(B-7)
        return;
    }
    if (!fn_IsValidArrDate(scwin.form, CheckArrDateArrVar2, 6)) {  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_IsValidArrDate — 폼·DOM 의존(B-7)
        return;
    }
    if (!fn_IsValidArr(scwin.form, CheckArrVar, CheckArrVarAlt)) {  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_IsValidArr — 폼·DOM 의존(B-7)
        return;
    }
    if (!await $c.fil.confirmJob('I')) {
        return;
    }
    scwin.rmCommaValueAll();
    scwin.form.action = '/list/elw.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'registerElw');
    await scwin.tx_fn_Register();
};

