        if(!fn_chkSaveElwPrc() ) return  ;  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_chkSaveElwPrc — 폼·DOM 의존(B-7)

        $c.util.getComponent("dma_RegisterReq").set("listProcsStatCd", CD_STAT_FIN);  /* 상장처리상태코드 */

        if (! await $c.fil.confirmJob('S') )  return ;

        scwin.form.action = '/list/elwPage.do';
